// Sentinel-1 GRD, VV polarization, IW mode, ascending orbit
var aoi = ee.Geometry.Point([12.5, 41.9]);

var collection = ee.ImageCollection('COPERNICUS/S1_GRD')
  .filterBounds(aoi)
  .filterDate('2024-01-01', '2024-03-01')
  .filter(ee.Filter.eq('instrumentMode', 'IW'))
  .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
  .filter(ee.Filter.eq('orbitProperties_pass', 'ASCENDING'))
  .select('VV');

print('Number of images:', collection.size());
Map.addLayer(collection.median(), {min: -20, max: 0}, 'Sentinel-1 VV (median)');

// Sentinel-2 Surface Reflectance, cloud-filtered, NDVI composite
var aoi = ee.Geometry.Point([12.5, 41.9]);

var collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
  .filterBounds(aoi)
  .filterDate('2024-06-01', '2024-08-31')
  .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

var addNDVI = function(img) {
  var ndvi = img.normalizedDifference(['B8', 'B4']).rename('NDVI');
  return img.addBands(ndvi);
};

var withNDVI = collection.map(addNDVI);
var ndviMedian = withNDVI.select('NDVI').median();

Map.centerObject(aoi, 10);
Map.addLayer(ndviMedian, {min: 0, max: 1, palette: ['white', 'green']}, 'NDVI median');

